CREATE FUNCTION mtch_immutable_role() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.role IS DISTINCT FROM OLD.role THEN RAISE EXCEPTION 'user role is immutable'; END IF; RETURN NEW; END $$;--> statement-breakpoint
CREATE TRIGGER user_immutable_role BEFORE UPDATE ON "user" FOR EACH ROW EXECUTE FUNCTION mtch_immutable_role();--> statement-breakpoint
CREATE FUNCTION mtch_immutable_offer() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF ROW(NEW.employer_user_id,NEW.company_id,NEW.specialist_user_id,NEW.search_profile_id,NEW.position_title,NEW.salary_min_rub,NEW.salary_max_rub,NEW.description,NEW.work_format,NEW.employment_type,NEW.message,NEW.search_profile_snapshot,NEW.specialist_snapshot,NEW.company_name_snapshot,NEW.score_at_send,NEW.sent_at) IS DISTINCT FROM ROW(OLD.employer_user_id,OLD.company_id,OLD.specialist_user_id,OLD.search_profile_id,OLD.position_title,OLD.salary_min_rub,OLD.salary_max_rub,OLD.description,OLD.work_format,OLD.employment_type,OLD.message,OLD.search_profile_snapshot,OLD.specialist_snapshot,OLD.company_name_snapshot,OLD.score_at_send,OLD.sent_at) THEN RAISE EXCEPTION 'offer terms are immutable'; END IF; RETURN NEW; END $$;--> statement-breakpoint
CREATE TRIGGER offer_immutable_terms BEFORE UPDATE ON offers FOR EACH ROW EXECUTE FUNCTION mtch_immutable_offer();
